/* Generated by flags-2-env from .cli-flags.toml. Do not edit. */

export interface CliEnvValues {
  readonly ftnl_flags_config?: string;
  readonly json: boolean;
  readonly localappdata?: string;
  readonly state_dir?: string;
  readonly timeout: number;
  readonly tunnel?: string;
  readonly url: string;
  readonly xdg_state_home?: string;
  readonly shell: string;
  readonly accept: ReadonlyArray<unknown>;
  readonly application_id?: string;
  readonly expires_in: number;
  readonly max_file_bytes: number;
  readonly max_files: number;
  readonly file_id?: string;
  readonly force: boolean;
  readonly out?: string;
  readonly file?: string;
  readonly job_id?: string;
  readonly media_type: string;
}

/** Pure: resolve values from an explicit lookup. */
export function loadFrom(lookup: (key: string) => string | undefined): CliEnvValues {
  return {
    ftnl_flags_config: nonEmpty(lookup("FTNL_FLAGS_CONFIG")),
    json: parseBool(lookup("FTNL_JSON"), false),
    localappdata: nonEmpty(lookup("LOCALAPPDATA")),
    state_dir: nonEmpty(lookup("FTNL_STATE_DIR")),
    timeout: parseIntValue(lookup("FTNL_TIMEOUT_MS"), 30000),
    tunnel: nonEmpty(lookup("FTNL_TUNNEL_ID")),
    url: nonEmpty(lookup("FTNL_BASE_URL")) ?? "https://api.file-tunnel.dev",
    xdg_state_home: nonEmpty(lookup("XDG_STATE_HOME")),
    shell: nonEmpty(lookup("FTNL_COMPLETION_SHELL")) ?? "bash",
    accept: nonEmpty(lookup("FTNL_ACCEPT")) ?? "[\"image/*\"]",
    application_id: nonEmpty(lookup("FTNL_APPLICATION_ID")),
    expires_in: parseIntValue(lookup("FTNL_EXPIRES_IN_SECONDS"), 600),
    max_file_bytes: parseIntValue(lookup("FTNL_MAX_FILE_BYTES"), 52428800),
    max_files: parseIntValue(lookup("FTNL_MAX_FILES"), 10),
    file_id: nonEmpty(lookup("FTNL_FILE_ID")),
    force: parseBool(lookup("FTNL_FORCE"), false),
    out: nonEmpty(lookup("FTNL_OUT")),
    file: nonEmpty(lookup("FTNL_FILE")),
    job_id: nonEmpty(lookup("FTNL_JOB_ID")),
    media_type: nonEmpty(lookup("FTNL_MEDIA_TYPE")) ?? "application/octet-stream",
  };
}

/** Effectful: read the process environment. */
export function loadFromOs(
  env: Record<string, string | undefined> = typeof process !== "undefined" ? process.env : {},
): CliEnvValues {
  return loadFrom((key) => env[key]);
}

function nonEmpty(raw: string | undefined): string | undefined {
  const value = raw?.trim();
  return value ? value : undefined;
}

function parseBool(raw: string | undefined, fallback: boolean): boolean {
  switch (raw?.trim()) {
    case "1":
    case "true":
    case "TRUE":
    case "yes":
    case "YES":
      return true;
    case "0":
    case "false":
    case "FALSE":
    case "no":
    case "NO":
      return false;
    default:
      return fallback;
  }
}

function parseIntValue(raw: string | undefined, fallback: number): number {
  const parsed = Number.parseInt(raw?.trim() ?? "", 10);
  return Number.isNaN(parsed) ? fallback : parsed;
}

function parseFloatValue(raw: string | undefined, fallback: number): number {
  const parsed = Number.parseFloat(raw?.trim() ?? "");
  return Number.isNaN(parsed) ? fallback : parsed;
}

function parseOptionalNumber(raw: string | undefined, asInt: boolean): number | undefined {
  const value = raw?.trim();
  if (!value) {
    return undefined;
  }
  const parsed = asInt ? Number.parseInt(value, 10) : Number.parseFloat(value);
  return Number.isNaN(parsed) ? undefined : parsed;
}

function nonempty(raw: string | undefined): string | undefined {
  const value = raw?.trim();
  return value ? value : undefined;
}

export function requireEnv(
  name: string,
  expectedType: string,
  examples: readonly string[],
  value: string | undefined,
): string {
  const trimmed = nonempty(value);
  if (trimmed) {
    return trimmed;
  }
  throw new MissingEnvError({ name, expectedType, examples });
}

function pick(
  keys: readonly string[],
  order: readonly string[],
  shell: Record<string, string | undefined>,
  dotenv: Record<string, string | undefined>,
  flags: Record<string, string | undefined>,
  fallback: string | undefined,
): string | undefined {
  for (const source of order) {
    const map = source === "flags" ? flags : source === "env_file" ? dotenv : shell;
    for (const key of keys) {
      const value = nonempty(map[key]);
      if (value !== undefined) {
        return value;
      }
    }
  }
  return nonempty(fallback);
}

function unquote(value: string): string {
  const trimmed = value.trim();
  if (
    (trimmed.startsWith("\"") && trimmed.endsWith("\"")) ||
    (trimmed.startsWith("'") && trimmed.endsWith("'"))
  ) {
    return trimmed.slice(1, -1);
  }
  return trimmed;
}

export function parseDotenv(text: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith("#")) {
      continue;
    }
    const body = line.startsWith("export ") ? line.slice("export ".length).trim() : line;
    const eq = body.indexOf("=");
    if (eq <= 0) {
      continue;
    }
    const key = body.slice(0, eq).trim();
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)) {
      continue;
    }
    out[key] = unquote(body.slice(eq + 1));
  }
  return out;
}

function dotenvEnabled(): boolean {
  const value = typeof process !== "undefined" ? process.env.FLAGS2ENV_DOTENV : undefined;
  return !["0", "false", "FALSE", "no", "NO"].includes(value?.trim() ?? "");
}

export function loadDotenvFiles(files: readonly string[]): Record<string, string> {
  if (!dotenvEnabled() || typeof process === "undefined") {
    return {};
  }
  let fs: { readFileSync: (path: string, encoding: string) => string } | undefined;
  try {
    fs = require("fs") as { readFileSync: (path: string, encoding: string) => string };
  } catch {
    return {};
  }
  return files.reduce<Record<string, string>>((acc, path) => {
    try {
      return { ...acc, ...parseDotenv(fs!.readFileSync(path, "utf8")) };
    } catch {
      return acc;
    }
  }, {});
}
export interface MissingEnv {
  readonly name: string;
  readonly expectedType: string;
  readonly examples: readonly string[];
}

export class MissingEnvError extends Error implements MissingEnv {
  readonly name: string;
  readonly expectedType: string;
  readonly examples: readonly string[];
  constructor(fields: MissingEnv) {
    super(`missing required environment variable ${fields.name}\n  expected type: ${fields.expectedType}\n  examples: ${fields.examples.join(", ")}`);
    this.name = fields.name;
    this.expectedType = fields.expectedType;
    this.examples = fields.examples;
  }
}

/** Resolve env-key -> value. Empty values fall through to the next source. */
export function loadEnvMap(
  shell: Record<string, string | undefined>,
  dotenv: Record<string, string | undefined>,
  flags: Record<string, string | undefined> = {},
): Record<string, string> {
  const out: Record<string, string> = {};
  const ftnl_flags_config = pick(["FTNL_FLAGS_CONFIG"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (ftnl_flags_config !== undefined) out["FTNL_FLAGS_CONFIG"] = ftnl_flags_config;
  const json = pick(["FTNL_JSON"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, "false");
  if (json !== undefined) out["FTNL_JSON"] = json;
  const localappdata = pick(["LOCALAPPDATA"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (localappdata !== undefined) out["LOCALAPPDATA"] = localappdata;
  const state_dir = pick(["FTNL_STATE_DIR"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (state_dir !== undefined) out["FTNL_STATE_DIR"] = state_dir;
  const timeout = pick(["FTNL_TIMEOUT_MS"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, "30000");
  if (timeout !== undefined) out["FTNL_TIMEOUT_MS"] = timeout;
  const tunnel = pick(["FTNL_TUNNEL_ID"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (tunnel !== undefined) out["FTNL_TUNNEL_ID"] = tunnel;
  const url = pick(["FTNL_BASE_URL"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, "https://api.file-tunnel.dev");
  if (url !== undefined) out["FTNL_BASE_URL"] = url;
  const xdg_state_home = pick(["XDG_STATE_HOME"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (xdg_state_home !== undefined) out["XDG_STATE_HOME"] = xdg_state_home;
  const shell = pick(["FTNL_COMPLETION_SHELL"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, "bash");
  if (shell !== undefined) out["FTNL_COMPLETION_SHELL"] = shell;
  const accept = pick(["FTNL_ACCEPT"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, "[\"image/*\"]");
  if (accept !== undefined) out["FTNL_ACCEPT"] = accept;
  const application_id = pick(["FTNL_APPLICATION_ID"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (application_id !== undefined) out["FTNL_APPLICATION_ID"] = application_id;
  const expires_in = pick(["FTNL_EXPIRES_IN_SECONDS"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, "600");
  if (expires_in !== undefined) out["FTNL_EXPIRES_IN_SECONDS"] = expires_in;
  const max_file_bytes = pick(["FTNL_MAX_FILE_BYTES"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, "52428800");
  if (max_file_bytes !== undefined) out["FTNL_MAX_FILE_BYTES"] = max_file_bytes;
  const max_files = pick(["FTNL_MAX_FILES"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, "10");
  if (max_files !== undefined) out["FTNL_MAX_FILES"] = max_files;
  const file_id = pick(["FTNL_FILE_ID"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (file_id !== undefined) out["FTNL_FILE_ID"] = file_id;
  const force = pick(["FTNL_FORCE"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, "false");
  if (force !== undefined) out["FTNL_FORCE"] = force;
  const out = pick(["FTNL_OUT"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (out !== undefined) out["FTNL_OUT"] = out;
  const file = pick(["FTNL_FILE"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (file !== undefined) out["FTNL_FILE"] = file;
  const job_id = pick(["FTNL_JOB_ID"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (job_id !== undefined) out["FTNL_JOB_ID"] = job_id;
  const media_type = pick(["FTNL_MEDIA_TYPE"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, "application/octet-stream");
  if (media_type !== undefined) out["FTNL_MEDIA_TYPE"] = media_type;
  return out;
}

const DOTENV_FILES: readonly string[] = [".env"];
/** Effectful overlay: `.env` files then `process.env`, ranked per key. */
export function loadEnvMapFromOs(
  shell: Record<string, string | undefined> = typeof process !== "undefined" ? process.env : {},
): Record<string, string> {
  return loadEnvMap(shell, loadDotenvFiles(DOTENV_FILES), {});
}
